source('code/lib/load.R')
stopifnot(apache_points(35.95,'temperature')==1,apache_points(129.5,'map')==2,apache_points(129.5,'sodium')==2,apache_points(44.9,'age')==0)
for(k in c('temperature','map','heart_rate','respiratory_rate','ph','bicarbonate','sodium','potassium','creatinine','hematocrit','wbc'))stopifnot(!anyNA(apache_points(seq(.1,200,length.out=1001),k)))
stopifnot(all(is.na(apache_points(c(NA,0,16,14.5),'gcs'))),apache_points(14,'gcs')==1)
l<-data.frame(lab_category=c('hemoglobin','hemoglobin','wbc','wbc','hematocrit','creatinine'),lab_value_numeric=c(10,100,5,5,.3,88.4),reference_unit=c('g/dL','g/L','10^3/µL','/hpf','L/L','umol/L'))
z<-apache_lab_normalize(l);stopifnot(identical(z$apache_value[c(1,2)],c(10,10)),z$apache_value[3]==5,is.na(z$apache_value[4]),z$apache_value[5]==30,z$apache_value[6]==1)
t0<-utc('2020-01-02 00:00:00')
stopifnot(is.na(apache_prior(t0,t0+60,.4)),apache_prior(t0+3600,t0,.4)==.4,is.na(apache_prior(t0+3601,t0,.4)),apache_oxygen_points(80,NA_real_,.4)==0,apache_oxygen_points(100,40,.6)==2,is.na(apache_oxygen_points(80,NA_real_,.6)))
ids<-c('a','b');d<-tibble::tibble(hospitalization_id=ids,t0=rep(t0,2),age_years=70)
v<-bind_rows(lapply(ids,function(id)tibble::tibble(hospitalization_id=id,recorded_dttm=t0+3600,vital_category=c('temp_c','sbp','dbp','heart_rate','respiratory_rate'),vital_value=c(37,120,60,80,16))))
v<-bind_rows(v,tibble::tibble(hospitalization_id='a',recorded_dttm=c(t0-1,t0+86400),vital_category='temp_c',vital_value=42))
l<-bind_rows(lapply(ids,function(id)tibble::tibble(hospitalization_id=id,lab_result_dttm=t0+3600,lab_category=c('po2_arterial','ph_arterial','sodium','potassium','creatinine','hemoglobin','wbc'),lab_value_numeric=c(80,7.4,140,4,.8,12,5),reference_unit=c('mmHg',NA,'mmol/L','mmol/L','mg/dL','g/dL','10^3/uL'))))
r<-tibble::tibble(hospitalization_id=ids,recorded_dttm=t0+3500,device_category='Nasal Cannula',fio2_set=.4)
g<-tibble::tibble(hospitalization_id=ids,recorded_dttm=t0+3600,assessment_category='gcs_total',numerical_value=c(15,NA))
a<-apache_adapted_features(d,list(vitals=v,labs=l,respiratory_support=r,patient_assessments=g))
ucum<-l;ucum$reference_unit[ucum$lab_category=='po2_arterial']<-'mm[Hg]'
ucum_score<-apache_adapted_features(d,list(vitals=v,labs=ucum,respiratory_support=r,patient_assessments=g))
stopifnot(identical(a,ucum_score))
gas<-data.frame(lab_category=c('po2_arterial','pco2_arterial','po2_arterial','po2_arterial'),lab_value_numeric=c(80,40,80,10),reference_unit=c(' mm[Hg] ','MM[HG]','mg/dL','kPa'))
normalized<-apache_lab_normalize(gas)
stopifnot(identical(normalized$apache_value[1:2],c(80,40)),is.na(normalized$apache_value[3]),normalized$apache_unit_rejected[3],abs(normalized$apache_value[4]-75.0062)<1e-8)
stopifnot(a$apache_adapted_total[1]==5,a$apache_observed_components[1]==12,a$apache_adapted_complete[1],!a$apache_adapted_complete[2],is.na(a$apache_adapted_total[2]),a$apache_observed_components[2]==11,a$apache_partial_sum[2]==5,a$apache_map_derived[1],all(is.na(a$apache_chronic_points)),all(is.na(a$apache_acute_renal_modifier)))
raw<-l;raw$lab_value_numeric[1]<-99
cached<-l[,setdiff(names(l),'reference_unit')]
enriched<-apache_enrich_cached_labs(cached,raw)
stopifnot(identical(enriched$labs$lab_value_numeric,cached$lab_value_numeric),enriched$audit$source_new_numeric_rows_ignored==1,enriched$audit$metadata_unmatched_rows==1)
cat('PASS: APACHE point boundaries, units, time pairing, first24h boundaries, complete-score missingness and frozen-value preservation\n')
